/**
 * Local content for the city pages (app/(main)/service-areas/[city]).
 *
 * Every city listed here gets an indexed page with its own overview, areas,
 * permit and bylaw notes, FAQs and sources. A city without an entry falls back
 * to the shared template and stays noindex and out of the sitemap.
 *
 * Rules for this file:
 * - Facts about a municipality (permit authority, bylaw hours, utilities,
 *   census figures, energy code) must come from the source listed for that
 *   city. Do not add a number without adding its source.
 * - Nothing here describes Woola work that is not already stated elsewhere on
 *   the site. No project counts, crew sizes or response times.
 * - Voice: a service manager explaining the city to a property manager. Plain
 *   sentences, no slogans, no em-dashes.
 */

export type CityLocal = {
  /** Title tag, without the "| Woola" suffix. */
  title: string;
  description: string;
  /** Two or three paragraphs on the building stock and what it means for the systems. */
  overview: string[];
  /** Label/value facts for the side card. */
  glance: { label: string; value: string }[];
  areas: { name: string; note: string }[];
  rules: { title: string; body: string }[];
  /** "division/service" refs, six per city. */
  services: string[];
  faqs: { q: string; a: string }[];
  /** Blog post slugs. */
  posts: string[];
  sources: { label: string; url: string }[];
  /** Month the sources were last checked, e.g. "November 2026". */
  checked: string;
};

